import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';
import { PITCH_SCALE } from './ProjectionService';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; // Maps NodeID -> Lowest Limit connecting to it
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
}

// Render Order Priority (Highest = Topmost/Outer Ring)
const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, // Cursor
    3: 1, // Strum
    2: 2, // Strings
    4: 3, // Brass
    5: 4, // Keys
    'arp': 5, // Arp
    1: 6  // Drone (Top)
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(bgCanvas, staticCanvas, state);
        this.renderDynamic(activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return {
                    bg: '#f8fafc', // Slate-50
                    line: '#94a3b8', // Slate-400
                    lineDim: 'rgba(148, 163, 184, 0.2)',
                    nodeText: '#334155', // Slate-700
                    nodeStroke: '#334155',
                    nodeFill: () => '#ffffff',
                    shadow: 'rgba(0,0,0,0.1)'
                };
            case 'blueprint':
                return {
                    bg: '#1e3a8a', // Blue-900
                    line: 'rgba(147, 197, 253, 0.4)', // Blue-300
                    lineDim: 'rgba(147, 197, 253, 0.1)',
                    nodeText: '#dbeafe', // Blue-100
                    nodeStroke: '#93c5fd',
                    nodeFill: () => '#172554', // Blue-950
                    shadow: 'rgba(0,0,0,0.3)'
                };
            case 'cyber':
                return {
                    bg: '#000000',
                    line: '#333333',
                    lineDim: '#111111',
                    nodeText: '#ffffff',
                    nodeStroke: '#444444',
                    nodeFill: () => '#000000',
                    shadow: '#00ff00'
                };
            case 'default':
            default:
                return {
                    bg: 'transparent',
                    line: '#666',
                    lineDim: 'rgba(255,255,255,0.1)',
                    nodeText: '#ffffff',
                    nodeStroke: 'transparent',
                    nodeFill: (limit, map) => map[limit] || '#666',
                    shadow: 'black'
                };
        }
    }

    private renderStatic(bgCanvas: HTMLCanvasElement, staticCanvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            linesLen: data.lines.length,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        // Render Lines on BG Canvas
        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        // Render Nodes on Static Canvas
        const ctx = staticCanvas.getContext('2d', { alpha: true });

        if (!ctx || !bgCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        // Sync Sizes
        if (staticCanvas.width !== view.w * dpr || staticCanvas.height !== view.h * dpr) {
            staticCanvas.width = view.w * dpr;
            staticCanvas.height = view.h * dpr;
            bgCanvas.width = view.w * dpr;
            bgCanvas.height = view.h * dpr;
        }

        // Clear & Reset
        bgCtx.setTransform(1, 0, 0, 1, 0, 0);
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
        bgCtx.scale(dpr, dpr);
        bgCtx.translate(-view.x, -view.y);

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, staticCanvas.width, staticCanvas.height);
        ctx.scale(dpr, dpr);
        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Lines with Consonance Weighting
        const linesByLimit: Record<number, number[]> = {};
        for (const line of data.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
            linesByLimit[line.limit].push(x1, y1, x2, y2);
        }

        bgCtx.lineCap = 'round';
        for (const limitStr in linesByLimit) {
            const limit = parseInt(limitStr);
            const coords = linesByLimit[limit];

            let color = settings.colors[limit] || '#666';
            if (isFlatSkin) {
                color = limit === 1 ? skin.line : skin.lineDim;
            }

            const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

            let weight = 1.0;
            let baseAlpha = 0.3;

            if (limit === 1) { weight = 3.0; baseAlpha = 0.5; } 
            else if (limit === 3) { weight = 2.5; baseAlpha = 0.45; }
            else if (limit === 5) { weight = 1.8; baseAlpha = 0.35; }
            else { weight = 0.8; baseAlpha = 0.2; }

            bgCtx.beginPath();
            for(let i=0; i<coords.length; i+=4) {
                bgCtx.moveTo(coords[i], coords[i+1]);
                bgCtx.lineTo(coords[i+2], coords[i+3]);
            }

            bgCtx.lineWidth = weight * visualSettings.size * effectiveScale;
            bgCtx.strokeStyle = color;
            bgCtx.globalAlpha = isFlatSkin ? 1.0 : baseAlpha * visualSettings.opacity;

            if (limit === 1) bgCtx.setLineDash([5 * effectiveScale, 5 * effectiveScale]);
            else bgCtx.setLineDash([]);
            bgCtx.stroke();
        }
        bgCtx.setLineDash([]); 

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis.size;
            const limitOpacity = topVis.opacity;
            const radius = Math.max(0, baseRadius * limitScale);

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();
            }

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = skin.nodeText;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale;
                    ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,${0.8 * limitOpacity})`;
                    if (settings.activeSkin === 'cyber') ctx.strokeStyle = '#fff';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, harmonicNeighbors,
            activeCursors, cursorPositions, effectiveScale, centerOffset, view, time, globalBend 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (activeCanvas.width !== view.w * dpr || activeCanvas.height !== view.h * dpr) {
            activeCanvas.width = view.w * dpr;
            activeCanvas.height = view.h * dpr;
        }

        activeCtx.setTransform(1, 0, 0, 1, 0, 0);
        activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);
        activeCtx.scale(dpr, dpr);
        activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const animationSpeed = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = settings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // BEND OFFSET: Applied to World Elements (Nodes, Lines) but NOT Cursors (Screen)
        const bendOffset = -globalBend * (PITCH_SCALE / 12) * effectiveScale;

        activeCtx.lineCap = 'round';

        // 0. Harmonic Neighbor Hints
        if (harmonicNeighbors.size > 0) {
            for (const [id, limit] of harmonicNeighbors.entries()) {
                const node = this.cachedNodeMap.get(id);
                if (!node) continue;

                const x = node.x * spacing + centerOffset;
                const y = node.y * spacing + centerOffset + bendOffset; // Apply Bend

                if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                const color = settings.colors[limit] || '#ffffff';
                const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis.size;
                const radius = Math.max(0, baseRadius * limitScale * 1.3); 

                activeCtx.beginPath();
                if (isDiamond) {
                    activeCtx.moveTo(x, y - radius);
                    activeCtx.lineTo(x + radius, y);
                    activeCtx.lineTo(x, y + radius);
                    activeCtx.lineTo(x - radius, y);
                } else {
                    activeCtx.arc(x, y, radius, 0, Math.PI * 2);
                }
                activeCtx.closePath();

                activeCtx.lineWidth = 3 * effectiveScale;
                activeCtx.strokeStyle = color;
                activeCtx.globalAlpha = 0.6;
                activeCtx.stroke();

                activeCtx.fillStyle = color;
                activeCtx.globalAlpha = 0.15;
                activeCtx.fill();
            }
        }

        // 1. Brightened Lines
        if (brightenedLines.length > 0) {
            activeCtx.setLineDash([]);
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset + bendOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset + bendOffset;

                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.line;

                activeCtx.beginPath();
                activeCtx.moveTo(x1, y1);
                activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = (settings.lineBrighteningWidth || 1.0) * effectiveScale;
                activeCtx.strokeStyle = limitColor;
                activeCtx.globalAlpha = isFlatSkin ? 0.6 : 0.8; 
                activeCtx.stroke();
            }
        }

        // 2. Active Lines
        activeCtx.setLineDash([]); 
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset + bendOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset + bendOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            let limitColor = settings.colors[line.limit] || '#666';
            if (isFlatSkin) limitColor = skin.nodeStroke;

            activeCtx.beginPath();
            activeCtx.moveTo(x1, y1);
            activeCtx.lineTo(x2, y2);
            activeCtx.lineWidth = (isFlatSkin ? 2 : 4) * effectiveScale;
            activeCtx.strokeStyle = limitColor;
            activeCtx.globalAlpha = 1.0;
            activeCtx.stroke();

            if (settings.isVoiceLeadingAnimationEnabled) {
                const grad = activeCtx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                const bright = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.7)';
                const clear = 'rgba(255,255,255,0)';

                grad.addColorStop(0, clear);
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, clear);
                grad.addColorStop(p, bright); 
                if (end < 1) grad.addColorStop(end, clear);
                grad.addColorStop(1, clear);

                activeCtx.strokeStyle = grad;
                activeCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale;
                activeCtx.globalAlpha = 0.3; 
                activeCtx.stroke();

                activeCtx.lineWidth = 4 * effectiveScale;
                activeCtx.globalAlpha = 1.0;
                activeCtx.stroke();
            }
        }

        // 3. Active Nodes
        for (const [id, activations] of visualLatchedNodes.entries()) {
             const node = this.cachedNodeMap.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset + bendOffset;

             if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

             const cTop = settings.colors[node.limitTop] || '#666';
             const cBottom = settings.colors[node.limitBottom] || '#666';
             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = settings.latchedZoomScale;
             const baseRad = Math.max(0, baseRadius * limitScale * zoomScale);

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - baseRad);
                activeCtx.lineTo(x + baseRad, y);
                activeCtx.lineTo(x, y + baseRad);
                activeCtx.lineTo(x - baseRad, y);
             } else {
                activeCtx.arc(x, y, baseRad, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isFlatSkin) {
                 activeCtx.fillStyle = '#ffffff'; 
                 if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#000000';
                 if (settings.activeSkin === 'blueprint') activeCtx.fillStyle = '#dbeafe';
             } else {
                 const grad = activeCtx.createLinearGradient(x, y - baseRad, x, y + baseRad);
                 grad.addColorStop(0.45, cTop);
                 grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
                 activeCtx.fillStyle = grad;
             }
             activeCtx.fill();

             const uniqueModes = new Set<number | string>();
             activations.forEach(a => uniqueModes.add(a.mode));

             const sortedModes = Array.from(uniqueModes).sort((a, b) => {
                 return (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99);
             });

             const ringWidth = 4 * effectiveScale;
             const ringGap = 2 * effectiveScale;

             sortedModes.forEach((mode, index) => {
                 const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';

                 // Strum/Arp Ripple
                 if (mode === 3 || mode === 'arp') {
                     const activation = activations.find(a => a.mode === mode);
                     if (activation) {
                         const age = time - activation.timestamp;
                         if (age < 500) { 
                             const rippleProgress = age / 500;
                             const rippleRadius = Math.max(0, baseRad + (rippleProgress * 40 * effectiveScale));
                             const rippleAlpha = 1.0 - rippleProgress;

                             activeCtx.beginPath();
                             activeCtx.arc(x, y, rippleRadius, 0, Math.PI * 2);
                             activeCtx.strokeStyle = color;
                             activeCtx.lineWidth = 2 * effectiveScale;
                             activeCtx.globalAlpha = rippleAlpha;
                             activeCtx.stroke();
                         }
                     }
                 }

                 const currentRadius = Math.max(0, baseRad + ringGap + (index * (ringWidth + ringGap)));

                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - currentRadius);
                    activeCtx.lineTo(x + currentRadius, y);
                    activeCtx.lineTo(x, y + currentRadius);
                    activeCtx.lineTo(x - currentRadius, y);
                 } else {
                    activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();

                 activeCtx.strokeStyle = color;
                 activeCtx.lineWidth = ringWidth;
                 activeCtx.globalAlpha = 0.8;

                 activeCtx.shadowBlur = 8 * effectiveScale;
                 activeCtx.shadowColor = color;
                 activeCtx.stroke();
                 activeCtx.shadowBlur = 0;
             });

             const combinedScale = settings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                activeCtx.fillStyle = isFlatSkin ? skin.nodeStroke : 'white';
                if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#00ff00';

                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (baseRad * spacingY));
                if (settings.showFractionBar) {
                    activeCtx.beginPath();
                    activeCtx.moveTo(x - (baseRad * 0.4), y);
                    activeCtx.lineTo(x + (baseRad * 0.4), y);
                    activeCtx.lineWidth = 1 * effectiveScale;
                    activeCtx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (baseRad * spacingY));
             }
        }

        // 4. Draw Cursors
        // NOTE: Cursors connect Node (World Space) to Pointer (Screen Space).
        // Since activeCanvas is NOT transformed via CSS, we must apply bendOffset ONLY to the Node coordinate.
        // The Pointer coordinate from cursorPositions is already in screen-relative space (scrolled).
        if (settings.isPitchBendEnabled) {
            activeCursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = this.cachedNodeMap.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset + bendOffset; // Apply Bend to Node

                         const pos = cursorPositions.get(c.pointerId);
                         if (!pos) return;

                         const cx = pos.x; // Pointer X
                         const cy = pos.y; // Pointer Y

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = isFlatSkin ? skin.nodeStroke : 'white';
                         activeCtx.lineWidth = 2 * effectiveScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
        }
    }
}

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

const ODD_IDENTITIES = [1, 3, 5, 7, 9, 11, 13, 15];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p as 3|5|7|11|13];
          for(let i=0; i<Math.abs(val); i++) {
              originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
          }
      });

      localQueue.push({ coords: origin.coords, ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 800;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime as 3|5|7|11|13];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      // @ts-ignore
                      const compLimit = (settings.limitComplexities && settings.limitComplexities[prime as 3|5|7|11|13]) ? settings.limitComplexities[prime as 3|5|7|11|13] : 1000;
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / (PRIME_RATIOS[prime as 3|5|7|11|13].n / PRIME_RATIOS[prime as 3|5|7|11|13].d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Strict Filtering: Only include identities explicitly enabled (not hidden)
    // Always include 1-Limit (Identity 1)
    const activeIdentities = ODD_IDENTITIES.filter(id => id === 1 || !settings.hiddenLimits.includes(id));
    const N = activeIdentities.length;

    // Scale factor to ensure nodes are visually separated
    const diamondSpacing = 200; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Stable ID based on Identities (e.g. "diamond-5-3") 
            // This ensures sustain persists correctly even if grid indices shift
            const id = `diamond-${idOton}-${idUton}`;

            // Layout indices rotated 45 degrees.
            // X is shifted by (N-1) so that the geometric center of the diamond is at x=0.
            // 1/1 (o=0, u=0) will be at x = -(N-1)*spacing.
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            nodes.push({
                id,
                // We keep [o, u] in coords to allow the UI to determine neighbor connectivity based on grid adjacency
                coords: [o, u, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y * 0.8, // Slightly squashed vertically
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  // Separate refs for layers to handle transforms independently
  const staticLayerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;

          const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
          if (isHybridMode) return; 

          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      // Add External Triggers (Arp)
      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      // Re-center if this is the first valid generation OR if the dynamic size changes significantly during initialization
      if (isInitialLoad && data.nodes.length > 0) {
          // Force a slightly longer delay to ensure DOM layout is settled and dimensions are correct
          const t = setTimeout(() => {
              centerScroll();
              // Only consider initial load complete if we have a real canvas size
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
          requestAnimationFrame(updateRect);
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                 const next = new Map(prev);
                 const nodeModes = next.get(hitNode.id) || new Map<number, number>();

                 if (nodeModes.has(latchMode)) {
                     nodeModes.delete(latchMode);
                 } else {
                     nodeModes.set(latchMode, Date.now());
                 }

                 if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                 else next.delete(hitNode.id);
                 return next;
             });
        }

        if (isBendEnabled || !isSustainActive) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const staticLayer = staticLayerRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      // Apply Pitch Bend (Pixel Offset) to the Static Layer container via CSS Transform
      // This is efficient and keeps static graphics synced with audio pitch
      if (staticLayer) {
          const bend = globalBendRef.current;
          const pixelOffset = -bend * (PITCH_SCALE / 12) * currentScale;
          const transform = `translate3d(0px, ${pixelOffset}px, 0px)`;
          staticLayer.style.transform = transform;
      }

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Background Layer - Fixed to view */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Static Canvas Layer (Transforms for Bend) */}
             <div ref={staticLayerRef} className="absolute inset-0 w-full h-full z-[5] will-change-transform">
                 <canvas ref={bgLineCanvasRef} className="absolute inset-0 w-full h-full z-[5]" />
                 <canvas ref={staticCanvasRef} className="absolute inset-0 w-full h-full z-[10]" />
             </div>

             {/* Dynamic Canvas Layer (No Transform, draws cursors in screen space) */}
             <canvas ref={dynamicCanvasRef} className="absolute inset-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Content Wrapper - Spacer ONLY */}
        <div 
            style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }}
        />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';
import { PITCH_SCALE } from './ProjectionService';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; // Maps NodeID -> Lowest Limit connecting to it
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
}

// Render Order Priority (Highest = Topmost/Outer Ring)
const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, // Cursor
    3: 1, // Strum
    2: 2, // Strings
    4: 3, // Brass
    5: 4, // Keys
    'arp': 5, // Arp
    1: 6  // Drone (Top)
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(bgCanvas, staticCanvas, state);
        this.renderDynamic(activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return {
                    bg: '#f8fafc', // Slate-50
                    line: '#94a3b8', // Slate-400
                    lineDim: 'rgba(148, 163, 184, 0.2)',
                    nodeText: '#334155', // Slate-700
                    nodeStroke: '#334155',
                    nodeFill: () => '#ffffff',
                    shadow: 'rgba(0,0,0,0.1)'
                };
            case 'blueprint':
                return {
                    bg: '#1e3a8a', // Blue-900
                    line: 'rgba(147, 197, 253, 0.4)', // Blue-300
                    lineDim: 'rgba(147, 197, 253, 0.1)',
                    nodeText: '#dbeafe', // Blue-100
                    nodeStroke: '#93c5fd',
                    nodeFill: () => '#172554', // Blue-950
                    shadow: 'rgba(0,0,0,0.3)'
                };
            case 'cyber':
                return {
                    bg: '#000000',
                    line: '#333333',
                    lineDim: '#111111',
                    nodeText: '#ffffff',
                    nodeStroke: '#444444',
                    nodeFill: () => '#000000',
                    shadow: '#00ff00'
                };
            case 'default':
            default:
                return {
                    bg: 'transparent',
                    line: '#666',
                    lineDim: 'rgba(255,255,255,0.1)',
                    nodeText: '#ffffff',
                    nodeStroke: 'transparent',
                    nodeFill: (limit, map) => map[limit] || '#666',
                    shadow: 'black'
                };
        }
    }

    private renderStatic(bgCanvas: HTMLCanvasElement, staticCanvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            // linesLen dependency removed as we no longer draw static lines
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        // Render Lines on BG Canvas
        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        // Render Nodes on Static Canvas
        const ctx = staticCanvas.getContext('2d', { alpha: true });

        if (!ctx || !bgCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        // Sync Sizes
        if (staticCanvas.width !== view.w * dpr || staticCanvas.height !== view.h * dpr) {
            staticCanvas.width = view.w * dpr;
            staticCanvas.height = view.h * dpr;
            bgCanvas.width = view.w * dpr;
            bgCanvas.height = view.h * dpr;
        }

        // Clear & Reset
        bgCtx.setTransform(1, 0, 0, 1, 0, 0);
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
        // bgCtx is no longer used for drawing static lines

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, staticCanvas.width, staticCanvas.height);
        ctx.scale(dpr, dpr);
        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis.size;
            const limitOpacity = topVis.opacity;
            const radius = Math.max(0, baseRadius * limitScale);

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();
            }

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = skin.nodeText;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale;
                    ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,${0.8 * limitOpacity})`;
                    if (settings.activeSkin === 'cyber') ctx.strokeStyle = '#fff';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, harmonicNeighbors,
            activeCursors, cursorPositions, effectiveScale, centerOffset, view, time, globalBend 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (activeCanvas.width !== view.w * dpr || activeCanvas.height !== view.h * dpr) {
            activeCanvas.width = view.w * dpr;
            activeCanvas.height = view.h * dpr;
        }

        activeCtx.setTransform(1, 0, 0, 1, 0, 0);
        activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);
        activeCtx.scale(dpr, dpr);
        activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const animationSpeed = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = settings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // BEND OFFSET: Applied to World Elements (Nodes, Lines) but NOT Cursors (Screen)
        const bendOffset = -globalBend * (PITCH_SCALE / 12) * effectiveScale;

        activeCtx.lineCap = 'round';

        // 0. Harmonic Neighbor Hints
        if (harmonicNeighbors.size > 0) {
            for (const [id, limit] of harmonicNeighbors.entries()) {
                const node = this.cachedNodeMap.get(id);
                if (!node) continue;

                const x = node.x * spacing + centerOffset;
                const y = node.y * spacing + centerOffset + bendOffset; // Apply Bend

                if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                const color = settings.colors[limit] || '#ffffff';
                const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis.size;
                const radius = Math.max(0, baseRadius * limitScale * 1.3); 

                activeCtx.beginPath();
                if (isDiamond) {
                    activeCtx.moveTo(x, y - radius);
                    activeCtx.lineTo(x + radius, y);
                    activeCtx.lineTo(x, y + radius);
                    activeCtx.lineTo(x - radius, y);
                } else {
                    activeCtx.arc(x, y, radius, 0, Math.PI * 2);
                }
                activeCtx.closePath();

                activeCtx.lineWidth = 3 * effectiveScale;
                activeCtx.strokeStyle = color;
                activeCtx.globalAlpha = 0.6;
                activeCtx.stroke();

                activeCtx.fillStyle = color;
                activeCtx.globalAlpha = 0.15;
                activeCtx.fill();
            }
        }

        // 1. Brightened Lines
        if (brightenedLines.length > 0) {
            activeCtx.setLineDash([]);
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset + bendOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset + bendOffset;

                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.line;

                activeCtx.beginPath();
                activeCtx.moveTo(x1, y1);
                activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = (settings.lineBrighteningWidth || 1.0) * effectiveScale;
                activeCtx.strokeStyle = limitColor;
                activeCtx.globalAlpha = isFlatSkin ? 0.6 : 0.8; 
                activeCtx.stroke();
            }
        }

        // 2. Active Lines
        activeCtx.setLineDash([]); 
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset + bendOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset + bendOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            let limitColor = settings.colors[line.limit] || '#666';
            if (isFlatSkin) limitColor = skin.nodeStroke;

            activeCtx.beginPath();
            activeCtx.moveTo(x1, y1);
            activeCtx.lineTo(x2, y2);
            activeCtx.lineWidth = (isFlatSkin ? 2 : 4) * effectiveScale;
            activeCtx.strokeStyle = limitColor;
            activeCtx.globalAlpha = 1.0;
            activeCtx.stroke();

            if (settings.isVoiceLeadingAnimationEnabled) {
                const grad = activeCtx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                const bright = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.7)';
                const clear = 'rgba(255,255,255,0)';

                grad.addColorStop(0, clear);
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, clear);
                grad.addColorStop(p, bright); 
                if (end < 1) grad.addColorStop(end, clear);
                grad.addColorStop(1, clear);

                activeCtx.strokeStyle = grad;
                activeCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale;
                activeCtx.globalAlpha = 0.3; 
                activeCtx.stroke();

                activeCtx.lineWidth = 4 * effectiveScale;
                activeCtx.globalAlpha = 1.0;
                activeCtx.stroke();
            }
        }

        // 3. Active Nodes
        for (const [id, activations] of visualLatchedNodes.entries()) {
             const node = this.cachedNodeMap.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset + bendOffset;

             if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

             const cTop = settings.colors[node.limitTop] || '#666';
             const cBottom = settings.colors[node.limitBottom] || '#666';
             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = settings.latchedZoomScale;
             const baseRad = Math.max(0, baseRadius * limitScale * zoomScale);

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - baseRad);
                activeCtx.lineTo(x + baseRad, y);
                activeCtx.lineTo(x, y + baseRad);
                activeCtx.lineTo(x - baseRad, y);
             } else {
                activeCtx.arc(x, y, baseRad, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isFlatSkin) {
                 activeCtx.fillStyle = '#ffffff'; 
                 if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#000000';
                 if (settings.activeSkin === 'blueprint') activeCtx.fillStyle = '#dbeafe';
             } else {
                 const grad = activeCtx.createLinearGradient(x, y - baseRad, x, y + baseRad);
                 grad.addColorStop(0.45, cTop);
                 grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
                 activeCtx.fillStyle = grad;
             }
             activeCtx.fill();

             const uniqueModes = new Set<number | string>();
             activations.forEach(a => uniqueModes.add(a.mode));

             const sortedModes = Array.from(uniqueModes).sort((a, b) => {
                 return (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99);
             });

             const ringWidth = 4 * effectiveScale;
             const ringGap = 2 * effectiveScale;

             sortedModes.forEach((mode, index) => {
                 const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';

                 // Strum/Arp Ripple
                 if (mode === 3 || mode === 'arp') {
                     const activation = activations.find(a => a.mode === mode);
                     if (activation) {
                         const age = time - activation.timestamp;
                         if (age < 500) { 
                             const rippleProgress = age / 500;
                             const rippleRadius = Math.max(0, baseRad + (rippleProgress * 40 * effectiveScale));
                             const rippleAlpha = 1.0 - rippleProgress;

                             activeCtx.beginPath();
                             activeCtx.arc(x, y, rippleRadius, 0, Math.PI * 2);
                             activeCtx.strokeStyle = color;
                             activeCtx.lineWidth = 2 * effectiveScale;
                             activeCtx.globalAlpha = rippleAlpha;
                             activeCtx.stroke();
                         }
                     }
                 }

                 const currentRadius = Math.max(0, baseRad + ringGap + (index * (ringWidth + ringGap)));

                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - currentRadius);
                    activeCtx.lineTo(x + currentRadius, y);
                    activeCtx.lineTo(x, y + currentRadius);
                    activeCtx.lineTo(x - currentRadius, y);
                 } else {
                    activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();

                 activeCtx.strokeStyle = color;
                 activeCtx.lineWidth = ringWidth;
                 activeCtx.globalAlpha = 0.8;

                 activeCtx.shadowBlur = 8 * effectiveScale;
                 activeCtx.shadowColor = color;
                 activeCtx.stroke();
                 activeCtx.shadowBlur = 0;
             });

             const combinedScale = settings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                activeCtx.fillStyle = isFlatSkin ? skin.nodeStroke : 'white';
                if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#00ff00';

                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (baseRad * spacingY));
                if (settings.showFractionBar) {
                    activeCtx.beginPath();
                    activeCtx.moveTo(x - (baseRad * 0.4), y);
                    activeCtx.lineTo(x + (baseRad * 0.4), y);
                    activeCtx.lineWidth = 1 * effectiveScale;
                    activeCtx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (baseRad * spacingY));
             }
        }

        // 4. Draw Cursors
        // NOTE: Cursors connect Node (World Space) to Pointer (Screen Space).
        // Since activeCanvas is NOT transformed via CSS, we must apply bendOffset ONLY to the Node coordinate.
        // The Pointer coordinate from cursorPositions is already in screen-relative space (scrolled).
        if (settings.isPitchBendEnabled) {
            activeCursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = this.cachedNodeMap.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset + bendOffset; // Apply Bend to Node

                         const pos = cursorPositions.get(c.pointerId);
                         if (!pos) return;

                         const cx = pos.x; // Pointer X
                         const cy = pos.y; // Pointer Y

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = isFlatSkin ? skin.nodeStroke : 'white';
                         activeCtx.lineWidth = 2 * effectiveScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
        }
    }
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  // Separate refs for layers to handle transforms independently
  const staticLayerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;

          const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
          if (isHybridMode) return; 

          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      // Add External Triggers (Arp)
      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      // Re-center if this is the first valid generation OR if the dynamic size changes significantly during initialization
      if (isInitialLoad && data.nodes.length > 0) {
          // Force a slightly longer delay to ensure DOM layout is settled and dimensions are correct
          const t = setTimeout(() => {
              centerScroll();
              // Only consider initial load complete if we have a real canvas size
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
          requestAnimationFrame(updateRect);
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     // REVERSE LOGIC: Sustain Active + Already Latched => DO NOT UNLATCH.
                     // Instead, initiate Group Bend if enabled.
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; // Don't trigger a new overlay voice, just bend existing
                     } else {
                         // If bend disabled, we do nothing (don't unlatch, don't retrigger cursor)
                         // Effectively "locks" the note.
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     // Sustain Active + New Note => Add to Latch
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 // Sustain Inactive => Standard Behavior (Toggle/Trigger)
                 if (isAlreadyLatched) {
                     // Explicitly allow un-latching when Sustain is OFF (e.g. cleaning up Drone mode)
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; // Don't play a new note if we are turning one off
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             // If Group Bend but we skipped cursor voice, we still need the cursor state for tracking
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             if (cursor.isGroupBend) {
                 // Group Bend: Apply to ALL latched nodes for this mode
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 // Standard Single Voice Bend
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        // If Group Bending, we don't trigger new notes or stop voices on hover change
        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
            // Reset Group Bend to original pitches
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         // Glide back to 1.0 (original ratio)
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, SynthPreset, PresetSlot, PlaybackMode, LimitType } from '../types';
import { PITCH_SCALE, getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import { GRID_CELL_SIZE } from '../constants';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  isCurrentSustainEnabled: boolean;
  globalScale?: number;
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  // Separate refs for layers to handle transforms independently
  const staticLayerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;

          const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
          if (isHybridMode) return; 

          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      // Add External Triggers (Arp)
      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      // Re-center if this is the first valid generation OR if the dynamic size changes significantly during initialization
      if (isInitialLoad && data.nodes.length > 0) {
          // Force a slightly longer delay to ensure DOM layout is settled and dimensions are correct
          const t = setTimeout(() => {
              centerScroll();
              // Only consider initial load complete if we have a real canvas size
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
          requestAnimationFrame(updateRect);
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     // REVERSE LOGIC: Sustain Active + Already Latched => DO NOT UNLATCH.
                     // Instead, initiate Group Bend if enabled.
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; // Don't trigger a new overlay voice, just bend existing
                     } else {
                         // If bend disabled, we do nothing (don't unlatch, don't retrigger cursor)
                         // Effectively "locks" the note.
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     // Sustain Active + New Note => Add to Latch
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 // Sustain Inactive => Standard Behavior (Toggle/Trigger)
                 if (isAlreadyLatched) {
                     // Explicitly allow un-latching when Sustain is OFF (e.g. cleaning up Drone mode)
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; // Don't play a new note if we are turning one off
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             // If Group Bend but we skipped cursor voice, we still need the cursor state for tracking
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             if (cursor.isGroupBend) {
                 // Group Bend: Apply to ALL latched nodes for this mode
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 // Standard Single Voice Bend
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        // If Group Bending, we don't trigger new notes or stop voices on hover change
        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
            // Reset Group Bend to original pitches
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         // Glide back to 1.0 (original ratio)
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              // @ts-ignore
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              // @ts-ignore
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              const period = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale);
              const stops = [];
              for(let i=0; i<=6; i++) {
                  const pct = (i/6)*100;
                  const hue = (settings.rainbowOffset + i*60);
                  stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
              }
              return { ...baseStyle, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${period}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';
import { PITCH_SCALE } from './ProjectionService';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; // Maps NodeID -> Lowest Limit connecting to it
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
}

// Render Order Priority (Highest = Topmost/Outer Ring)
const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, // Cursor
    3: 1, // Strum
    2: 2, // Strings
    4: 3, // Brass
    5: 4, // Keys
    'arp': 5, // Arp
    1: 6  // Drone (Top)
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(bgCanvas, staticCanvas, state);
        this.renderDynamic(activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return {
                    bg: '#f8fafc', // Slate-50
                    line: '#94a3b8', // Slate-400
                    lineDim: 'rgba(148, 163, 184, 0.2)',
                    nodeText: '#334155', // Slate-700
                    nodeStroke: '#334155',
                    nodeFill: () => '#ffffff',
                    shadow: 'rgba(0,0,0,0.1)'
                };
            case 'blueprint':
                return {
                    bg: '#1e3a8a', // Blue-900
                    line: 'rgba(147, 197, 253, 0.4)', // Blue-300
                    lineDim: 'rgba(147, 197, 253, 0.1)',
                    nodeText: '#dbeafe', // Blue-100
                    nodeStroke: '#93c5fd',
                    nodeFill: () => '#172554', // Blue-950
                    shadow: 'rgba(0,0,0,0.3)'
                };
            case 'cyber':
                return {
                    bg: '#000000',
                    line: '#333333',
                    lineDim: '#111111',
                    nodeText: '#ffffff',
                    nodeStroke: '#444444',
                    nodeFill: () => '#000000',
                    shadow: '#00ff00'
                };
            case 'default':
            default:
                return {
                    bg: 'transparent',
                    line: '#666',
                    lineDim: 'rgba(255,255,255,0.1)',
                    nodeText: '#ffffff',
                    nodeStroke: 'transparent',
                    nodeFill: (limit, map) => map[limit] || '#666',
                    shadow: 'black'
                };
        }
    }

    private renderStatic(bgCanvas: HTMLCanvasElement, staticCanvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        // Render Lines on BG Canvas
        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        // Render Nodes on Static Canvas
        const ctx = staticCanvas.getContext('2d', { alpha: true });

        if (!ctx || !bgCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        // Sync Sizes
        if (staticCanvas.width !== view.w * dpr || staticCanvas.height !== view.h * dpr) {
            staticCanvas.width = view.w * dpr;
            staticCanvas.height = view.h * dpr;
            bgCanvas.width = view.w * dpr;
            bgCanvas.height = view.h * dpr;
        }

        // Clear & Reset
        bgCtx.setTransform(1, 0, 0, 1, 0, 0);
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, staticCanvas.width, staticCanvas.height);
        ctx.scale(dpr, dpr);
        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis?.size ?? 1;
            const limitOpacity = topVis?.opacity ?? 1;
            const radius = Math.max(0, baseRadius * limitScale);

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();
            }

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = skin.nodeText;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale;
                    ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,${0.8 * limitOpacity})`;
                    if (settings.activeSkin === 'cyber') ctx.strokeStyle = '#fff';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, harmonicNeighbors,
            activeCursors, cursorPositions, effectiveScale, centerOffset, view, time, globalBend 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (activeCanvas.width !== view.w * dpr || activeCanvas.height !== view.h * dpr) {
            activeCanvas.width = view.w * dpr;
            activeCanvas.height = view.h * dpr;
        }

        activeCtx.setTransform(1, 0, 0, 1, 0, 0);
        activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);
        activeCtx.scale(dpr, dpr);
        activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const animationSpeed = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = settings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        const bendOffset = -globalBend * (PITCH_SCALE / 12) * effectiveScale;

        activeCtx.lineCap = 'round';

        // 0. Harmonic Neighbor Hints
        if (harmonicNeighbors && harmonicNeighbors.size > 0) {
            for (const [id, limit] of harmonicNeighbors.entries()) {
                const node = this.cachedNodeMap.get(id);
                if (!node) continue;

                const x = node.x * spacing + centerOffset;
                const y = node.y * spacing + centerOffset + bendOffset;

                if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                const color = settings.colors[limit] || '#ffffff';
                const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis?.size ?? 1;
                const radius = Math.max(0, baseRadius * limitScale * 1.3); 

                activeCtx.beginPath();
                if (isDiamond) {
                    activeCtx.moveTo(x, y - radius);
                    activeCtx.lineTo(x + radius, y);
                    activeCtx.lineTo(x, y + radius);
                    activeCtx.lineTo(x - radius, y);
                } else {
                    activeCtx.arc(x, y, radius, 0, Math.PI * 2);
                }
                activeCtx.closePath();

                activeCtx.lineWidth = 3 * effectiveScale;
                activeCtx.strokeStyle = color;
                activeCtx.globalAlpha = 0.6;
                activeCtx.stroke();

                activeCtx.fillStyle = color;
                activeCtx.globalAlpha = 0.15;
                activeCtx.fill();
            }
        }

        // 1. Brightened Lines
        if (brightenedLines && brightenedLines.length > 0) {
            activeCtx.setLineDash([]);
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset + bendOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset + bendOffset;

                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.line;

                activeCtx.beginPath();
                activeCtx.moveTo(x1, y1);
                activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = (settings.lineBrighteningWidth || 1.0) * effectiveScale;
                activeCtx.strokeStyle = limitColor;
                activeCtx.globalAlpha = isFlatSkin ? 0.6 : 0.8; 
                activeCtx.stroke();
            }
        }

        // 2. Active Lines
        activeCtx.setLineDash([]); 
        if (activeLines) {
            for (const line of activeLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset + bendOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset + bendOffset;
                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.nodeStroke;

                activeCtx.beginPath();
                activeCtx.moveTo(x1, y1);
                activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = (isFlatSkin ? 2 : 4) * effectiveScale;
                activeCtx.strokeStyle = limitColor;
                activeCtx.globalAlpha = 1.0;
                activeCtx.stroke();

                if (settings.isVoiceLeadingAnimationEnabled) {
                    const grad = activeCtx.createLinearGradient(x1, y1, x2, y2);
                    const p = flowPhase;
                    const bright = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.7)';
                    const clear = 'rgba(255,255,255,0)';

                    grad.addColorStop(0, clear);
                    const pulseWidth = 0.2;
                    const start = Math.max(0, p - pulseWidth);
                    const end = Math.min(1, p + pulseWidth);
                    if (start > 0) grad.addColorStop(start, clear);
                    grad.addColorStop(p, bright); 
                    if (end < 1) grad.addColorStop(end, clear);
                    grad.addColorStop(1, clear);

                    activeCtx.strokeStyle = grad;
                    activeCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale;
                    activeCtx.globalAlpha = 0.3; 
                    activeCtx.stroke();

                    activeCtx.lineWidth = 4 * effectiveScale;
                    activeCtx.globalAlpha = 1.0;
                    activeCtx.stroke();
                }
            }
        }

        // 3. Active Nodes
        if (visualLatchedNodes) {
            for (const [id, activations] of visualLatchedNodes.entries()) {
                 const node = this.cachedNodeMap.get(id);
                 if (!node) continue;

                 const x = node.x * spacing + centerOffset;
                 const y = node.y * spacing + centerOffset + bendOffset;

                 if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                 const cTop = settings.colors[node.limitTop] || '#666';
                 const cBottom = settings.colors[node.limitBottom] || '#666';
                 const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                 const limitScale = vis?.size ?? 1;
                 const zoomScale = settings.latchedZoomScale;
                 const baseRad = Math.max(0, baseRadius * limitScale * zoomScale);

                 activeCtx.globalAlpha = 1.0; 
                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - baseRad);
                    activeCtx.lineTo(x + baseRad, y);
                    activeCtx.lineTo(x, y + baseRad);
                    activeCtx.lineTo(x - baseRad, y);
                 } else {
                    activeCtx.arc(x, y, baseRad, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();

                 if (isFlatSkin) {
                     activeCtx.fillStyle = '#ffffff'; 
                     if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#000000';
                     if (settings.activeSkin === 'blueprint') activeCtx.fillStyle = '#dbeafe';
                 } else {
                     const grad = activeCtx.createLinearGradient(x, y - baseRad, x, y + baseRad);
                     grad.addColorStop(0.45, cTop);
                     grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
                     activeCtx.fillStyle = grad;
                 }
                 activeCtx.fill();

                 const uniqueModes = new Set<number | string>();
                 activations.forEach(a => uniqueModes.add(a.mode));

                 const sortedModes = Array.from(uniqueModes).sort((a, b) => {
                     return (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99);
                 });

                 const ringWidth = 4 * effectiveScale;
                 const ringGap = 2 * effectiveScale;

                 sortedModes.forEach((mode, index) => {
                     const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';

                     // Strum/Arp Ripple
                     if (mode === 3 || mode === 'arp') {
                         const activation = activations.find(a => a.mode === mode);
                         if (activation) {
                             const age = time - activation.timestamp;
                             if (age < 500) { 
                                 const rippleProgress = age / 500;
                                 const rippleRadius = Math.max(0, baseRad + (rippleProgress * 40 * effectiveScale));
                                 const rippleAlpha = 1.0 - rippleProgress;

                                 activeCtx.beginPath();
                                 activeCtx.arc(x, y, rippleRadius, 0, Math.PI * 2);
                                 activeCtx.strokeStyle = color;
                                 activeCtx.lineWidth = 2 * effectiveScale;
                                 activeCtx.globalAlpha = rippleAlpha;
                                 activeCtx.stroke();
                             }
                         }
                     }

                     const currentRadius = Math.max(0, baseRad + ringGap + (index * (ringWidth + ringGap)));

                     activeCtx.beginPath();
                     if (isDiamond) {
                        activeCtx.moveTo(x, y - currentRadius);
                        activeCtx.lineTo(x + currentRadius, y);
                        activeCtx.lineTo(x, y + currentRadius);
                        activeCtx.lineTo(x - currentRadius, y);
                     } else {
                        activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                     }
                     activeCtx.closePath();

                     activeCtx.strokeStyle = color;
                     activeCtx.lineWidth = ringWidth;
                     activeCtx.globalAlpha = 0.8;

                     activeCtx.shadowBlur = 8 * effectiveScale;
                     activeCtx.shadowColor = color;
                     activeCtx.stroke();
                     activeCtx.shadowBlur = 0;
                 });

                 const combinedScale = settings.buttonSizeScale * limitScale * zoomScale;
                 if (combinedScale > 0.4) {
                    activeCtx.fillStyle = isFlatSkin ? skin.nodeStroke : 'white';
                    if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#00ff00';

                    activeCtx.textAlign = 'center';
                    activeCtx.textBaseline = 'middle';
                    let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                    activeCtx.font = `bold ${fontSize}px sans-serif`; 
                    const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                    activeCtx.fillText(node.n.toString(), x, y - (baseRad * spacingY));
                    if (settings.showFractionBar) {
                        activeCtx.beginPath();
                        activeCtx.moveTo(x - (baseRad * 0.4), y);
                        activeCtx.lineTo(x + (baseRad * 0.4), y);
                        activeCtx.lineWidth = 1 * effectiveScale;
                        activeCtx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'white';
                        activeCtx.stroke();
                    }
                    activeCtx.fillText(node.d.toString(), x, y + (baseRad * spacingY));
                 }
            }
        }

        // 4. Draw Cursors
        if (settings.isPitchBendEnabled && activeCursors) {
            activeCursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = this.cachedNodeMap.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset + bendOffset; // Apply Bend to Node

                         const pos = cursorPositions.get(c.pointerId);
                         if (!pos) return;

                         const cx = pos.x; // Pointer X
                         const cy = pos.y; // Pointer Y

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = isFlatSkin ? skin.nodeStroke : 'white';
                         activeCtx.lineWidth = 2 * effectiveScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
        }
    }
}

// ... existing imports
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, SynthPreset, PresetSlot, PlaybackMode, LimitType } from '../types';
import { PITCH_SCALE, getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import { GRID_CELL_SIZE } from '../constants';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';

// ... interface definitions ...
export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  isCurrentSustainEnabled: boolean;
  globalScale?: number;
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  // Separate refs for layers to handle transforms independently
  const staticLayerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              if (modeMap) modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      if (persistentLatches) {
          persistentLatches.forEach((modeMap, nodeId) => {
              const activations: NodeActivation[] = [];
              if (modeMap) {
                  modeMap.forEach((timestamp, mode) => {
                      let pId = 'normal';
                      if (mode === 1) pId = 'latch';
                      else if (mode === 3) pId = 'strum';
                      else if (mode === 4) pId = 'brass';
                      else if (mode === 5) pId = 'keys';
                      else if (mode === 6) pId = 'percussion';
                      activations.push({ mode, timestamp, presetId: pId });
                  });
              }
              effective.set(nodeId, activations);
          });
      }

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      if (audioLatchedNodes) audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      if (activeCursors) {
          activeCursors.forEach(cursor => {
              const isSustainingInstrument = latchMode >= 1; 
              const isSustainActive = isCurrentSustainEnabled;
              const isBendEnabled = settings.isPitchBendEnabled;

              const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
              if (isHybridMode) return; 

              const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
              if (isMelodic && cursor.hoverNodeId) {
                  const nodeId = cursor.hoverNodeId;
                  if (!visual.has(nodeId)) visual.set(nodeId, []);
                  const list = visual.get(nodeId)!;
                  const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
                  list.push(activation);
                  list.sort((a, b) => a.timestamp - b.timestamp);
              }
          });
      }

      // Add External Triggers (Arp)
      if (externalTriggers) {
          externalTriggers.forEach((timestamp, nodeId) => {
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          });
      }

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      if (activeCursors) activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      if (visualLatchedNodes) visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (!latched || latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || !visualLatchedNodes || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

// ... rest of the file ...
// (Refs, Handlers, Render logic same as previous step, but ensuring types are clean)

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n && modeMap) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && data.nodes.length > 0) {
          const t = setTimeout(() => {
              centerScroll();
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
          requestAnimationFrame(updateRect);
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap && latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; 
                     } else {
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 if (isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; 
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             if (cursor.isGroupBend) {
                 // Group Bend
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap && modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 // Standard Single Voice Bend
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        // If Group Bending, we don't trigger new notes or stop voices on hover change
        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap && modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  // ... (getBackgroundStyle same as before) ...
  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              return { ...baseStyle, background: `linear-gradient(to bottom, #111, #222)` }; // Simplify for now
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';
import { PITCH_SCALE } from './ProjectionService';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; 
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
}

const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, 3: 1, 2: 2, 4: 3, 5: 4, 'arp': 5, 1: 6 
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(bgCanvas, staticCanvas, state);
        this.renderDynamic(activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return {
                    bg: '#f8fafc',
                    line: '#94a3b8',
                    lineDim: 'rgba(148, 163, 184, 0.2)',
                    nodeText: '#334155',
                    nodeStroke: '#334155',
                    nodeFill: () => '#ffffff',
                    shadow: 'rgba(0,0,0,0.1)'
                };
            case 'blueprint':
                return {
                    bg: '#1e3a8a',
                    line: 'rgba(147, 197, 253, 0.4)',
                    lineDim: 'rgba(147, 197, 253, 0.1)',
                    nodeText: '#dbeafe',
                    nodeStroke: '#93c5fd',
                    nodeFill: () => '#172554',
                    shadow: 'rgba(0,0,0,0.3)'
                };
            case 'cyber':
                return {
                    bg: '#000000',
                    line: '#333333',
                    lineDim: '#111111',
                    nodeText: '#ffffff',
                    nodeStroke: '#444444',
                    nodeFill: () => '#000000',
                    shadow: '#00ff00'
                };
            default:
                return {
                    bg: 'transparent',
                    line: '#666',
                    lineDim: 'rgba(255,255,255,0.1)',
                    nodeText: '#ffffff',
                    nodeStroke: 'transparent',
                    nodeFill: (limit, map) => map[limit] || '#666',
                    shadow: 'black'
                };
        }
    }

    private renderStatic(bgCanvas: HTMLCanvasElement, staticCanvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        // Include view dimensions in deps to trigger redraw on resize
        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const ctx = staticCanvas.getContext('2d', { alpha: true });

        if (!ctx || !bgCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        // Sync sizes to viewport
        if (staticCanvas.width !== view.w * dpr || staticCanvas.height !== view.h * dpr) {
            staticCanvas.width = view.w * dpr;
            staticCanvas.height = view.h * dpr;
            bgCanvas.width = view.w * dpr;
            bgCanvas.height = view.h * dpr;
        }

        bgCtx.setTransform(1, 0, 0, 1, 0, 0);
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, staticCanvas.width, staticCanvas.height);

        // Apply Transform: Scale for Retina, Translate for Scroll
        ctx.scale(dpr, dpr);
        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis?.size ?? 1;
            const limitOpacity = topVis?.opacity ?? 1;
            const radius = Math.max(0, baseRadius * limitScale);

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();
            }

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = skin.nodeText;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale;
                    ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,${0.8 * limitOpacity})`;
                    if (settings.activeSkin === 'cyber') ctx.strokeStyle = '#fff';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, harmonicNeighbors,
            activeCursors, cursorPositions, effectiveScale, centerOffset, view, time, globalBend 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (activeCanvas.width !== view.w * dpr || activeCanvas.height !== view.h * dpr) {
            activeCanvas.width = view.w * dpr;
            activeCanvas.height = view.h * dpr;
        }

        activeCtx.setTransform(1, 0, 0, 1, 0, 0);
        activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);
        activeCtx.scale(dpr, dpr);
        activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const animationSpeed = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = settings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        const bendOffset = -globalBend * (PITCH_SCALE / 12) * effectiveScale;

        activeCtx.lineCap = 'round';

        // 0. Harmonic Neighbors
        if (harmonicNeighbors && harmonicNeighbors.size > 0) {
            for (const [id, limit] of harmonicNeighbors.entries()) {
                const node = this.cachedNodeMap.get(id);
                if (!node) continue;

                const x = node.x * spacing + centerOffset;
                const y = node.y * spacing + centerOffset + bendOffset;

                if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                const color = settings.colors[limit] || '#ffffff';
                const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis?.size ?? 1;
                const radius = Math.max(0, baseRadius * limitScale * 1.3); 

                activeCtx.beginPath();
                if (isDiamond) {
                    activeCtx.moveTo(x, y - radius);
                    activeCtx.lineTo(x + radius, y);
                    activeCtx.lineTo(x, y + radius);
                    activeCtx.lineTo(x - radius, y);
                } else {
                    activeCtx.arc(x, y, radius, 0, Math.PI * 2);
                }
                activeCtx.closePath();

                activeCtx.lineWidth = 3 * effectiveScale;
                activeCtx.strokeStyle = color;
                activeCtx.globalAlpha = 0.6;
                activeCtx.stroke();

                activeCtx.fillStyle = color;
                activeCtx.globalAlpha = 0.15;
                activeCtx.fill();
            }
        }

        // 1. Brightened Lines
        if (brightenedLines && brightenedLines.length > 0) {
            activeCtx.setLineDash([]);
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset + bendOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset + bendOffset;

                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.line;

                activeCtx.beginPath();
                activeCtx.moveTo(x1, y1);
                activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = (settings.lineBrighteningWidth || 1.0) * effectiveScale;
                activeCtx.strokeStyle = limitColor;
                activeCtx.globalAlpha = isFlatSkin ? 0.6 : 0.8; 
                activeCtx.stroke();
            }
        }

        // 2. Active Lines
        activeCtx.setLineDash([]); 
        if (activeLines) {
            for (const line of activeLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset + bendOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset + bendOffset;
                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.nodeStroke;

                activeCtx.beginPath();
                activeCtx.moveTo(x1, y1);
                activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = (isFlatSkin ? 2 : 4) * effectiveScale;
                activeCtx.strokeStyle = limitColor;
                activeCtx.globalAlpha = 1.0;
                activeCtx.stroke();

                if (settings.isVoiceLeadingAnimationEnabled) {
                    const grad = activeCtx.createLinearGradient(x1, y1, x2, y2);
                    const p = flowPhase;
                    const bright = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.7)';
                    const clear = 'rgba(255,255,255,0)';

                    grad.addColorStop(0, clear);
                    const pulseWidth = 0.2;
                    const start = Math.max(0, p - pulseWidth);
                    const end = Math.min(1, p + pulseWidth);
                    if (start > 0) grad.addColorStop(start, clear);
                    grad.addColorStop(p, bright); 
                    if (end < 1) grad.addColorStop(end, clear);
                    grad.addColorStop(1, clear);

                    activeCtx.strokeStyle = grad;
                    activeCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale;
                    activeCtx.globalAlpha = 0.3; 
                    activeCtx.stroke();

                    activeCtx.lineWidth = 4 * effectiveScale;
                    activeCtx.globalAlpha = 1.0;
                    activeCtx.stroke();
                }
            }
        }

        // 3. Active Nodes
        if (visualLatchedNodes) {
            for (const [id, activations] of visualLatchedNodes.entries()) {
                 const node = this.cachedNodeMap.get(id);
                 if (!node) continue;

                 const x = node.x * spacing + centerOffset;
                 const y = node.y * spacing + centerOffset + bendOffset;

                 if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                 const cTop = settings.colors[node.limitTop] || '#666';
                 const cBottom = settings.colors[node.limitBottom] || '#666';
                 const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                 const limitScale = vis?.size ?? 1;
                 const zoomScale = settings.latchedZoomScale;
                 const baseRad = Math.max(0, baseRadius * limitScale * zoomScale);

                 activeCtx.globalAlpha = 1.0; 
                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - baseRad);
                    activeCtx.lineTo(x + baseRad, y);
                    activeCtx.lineTo(x, y + baseRad);
                    activeCtx.lineTo(x - baseRad, y);
                 } else {
                    activeCtx.arc(x, y, baseRad, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();

                 if (isFlatSkin) {
                     activeCtx.fillStyle = '#ffffff'; 
                     if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#000000';
                     if (settings.activeSkin === 'blueprint') activeCtx.fillStyle = '#dbeafe';
                 } else {
                     const grad = activeCtx.createLinearGradient(x, y - baseRad, x, y + baseRad);
                     grad.addColorStop(0.45, cTop);
                     grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
                     activeCtx.fillStyle = grad;
                 }
                 activeCtx.fill();

                 const uniqueModes = new Set<number | string>();
                 activations.forEach(a => uniqueModes.add(a.mode));

                 const sortedModes = Array.from(uniqueModes).sort((a, b) => {
                     return (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99);
                 });

                 const ringWidth = 4 * effectiveScale;
                 const ringGap = 2 * effectiveScale;

                 sortedModes.forEach((mode, index) => {
                     const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';

                     // Strum/Arp Ripple
                     if (mode === 3 || mode === 'arp') {
                         const activation = activations.find(a => a.mode === mode);
                         if (activation) {
                             const age = time - activation.timestamp;
                             if (age < 500) { 
                                 const rippleProgress = age / 500;
                                 const rippleRadius = Math.max(0, baseRad + (rippleProgress * 40 * effectiveScale));
                                 const rippleAlpha = 1.0 - rippleProgress;

                                 activeCtx.beginPath();
                                 activeCtx.arc(x, y, rippleRadius, 0, Math.PI * 2);
                                 activeCtx.strokeStyle = color;
                                 activeCtx.lineWidth = 2 * effectiveScale;
                                 activeCtx.globalAlpha = rippleAlpha;
                                 activeCtx.stroke();
                             }
                         }
                     }

                     const currentRadius = Math.max(0, baseRad + ringGap + (index * (ringWidth + ringGap)));

                     activeCtx.beginPath();
                     if (isDiamond) {
                        activeCtx.moveTo(x, y - currentRadius);
                        activeCtx.lineTo(x + currentRadius, y);
                        activeCtx.lineTo(x, y + currentRadius);
                        activeCtx.lineTo(x - currentRadius, y);
                     } else {
                        activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                     }
                     activeCtx.closePath();

                     activeCtx.strokeStyle = color;
                     activeCtx.lineWidth = ringWidth;
                     activeCtx.globalAlpha = 0.8;

                     activeCtx.shadowBlur = 8 * effectiveScale;
                     activeCtx.shadowColor = color;
                     activeCtx.stroke();
                     activeCtx.shadowBlur = 0;
                 });

                 const combinedScale = settings.buttonSizeScale * limitScale * zoomScale;
                 if (combinedScale > 0.4) {
                    activeCtx.fillStyle = isFlatSkin ? skin.nodeStroke : 'white';
                    if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#00ff00';

                    activeCtx.textAlign = 'center';
                    activeCtx.textBaseline = 'middle';
                    let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                    activeCtx.font = `bold ${fontSize}px sans-serif`; 
                    const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                    activeCtx.fillText(node.n.toString(), x, y - (baseRad * spacingY));
                    if (settings.showFractionBar) {
                        activeCtx.beginPath();
                        activeCtx.moveTo(x - (baseRad * 0.4), y);
                        activeCtx.lineTo(x + (baseRad * 0.4), y);
                        activeCtx.lineWidth = 1 * effectiveScale;
                        activeCtx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'white';
                        activeCtx.stroke();
                    }
                    activeCtx.fillText(node.d.toString(), x, y + (baseRad * spacingY));
                 }
            }
        }

        // 4. Draw Cursors
        if (settings.isPitchBendEnabled && activeCursors) {
            activeCursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = this.cachedNodeMap.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset + bendOffset; 

                         const pos = cursorPositions.get(c.pointerId);
                         if (!pos) return;

                         const cx = pos.x; 
                         const cy = pos.y; 

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = isFlatSkin ? skin.nodeStroke : 'white';
                         activeCtx.lineWidth = 2 * effectiveScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
        }
    }
}

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, SynthPreset, PresetSlot, PlaybackMode, LimitType } from '../types';
import { PITCH_SCALE, getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import { GRID_CELL_SIZE } from '../constants';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  isCurrentSustainEnabled: boolean;
  globalScale?: number;
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              if (modeMap) modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      if (persistentLatches) {
          persistentLatches.forEach((modeMap, nodeId) => {
              const activations: NodeActivation[] = [];
              if (modeMap) {
                  modeMap.forEach((timestamp, mode) => {
                      let pId = 'normal';
                      if (mode === 1) pId = 'latch';
                      else if (mode === 3) pId = 'strum';
                      else if (mode === 4) pId = 'brass';
                      else if (mode === 5) pId = 'keys';
                      else if (mode === 6) pId = 'percussion';
                      activations.push({ mode, timestamp, presetId: pId });
                  });
              }
              effective.set(nodeId, activations);
          });
      }

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      if (audioLatchedNodes) audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      if (activeCursors) {
          activeCursors.forEach(cursor => {
              const isSustainingInstrument = latchMode >= 1; 
              const isSustainActive = isCurrentSustainEnabled;
              const isBendEnabled = settings.isPitchBendEnabled;

              const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
              if (isHybridMode) return; 

              const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
              if (isMelodic && cursor.hoverNodeId) {
                  const nodeId = cursor.hoverNodeId;
                  if (!visual.has(nodeId)) visual.set(nodeId, []);
                  const list = visual.get(nodeId)!;
                  const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
                  list.push(activation);
                  list.sort((a, b) => a.timestamp - b.timestamp);
              }
          });
      }

      if (externalTriggers) {
          externalTriggers.forEach((timestamp, nodeId) => {
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          });
      }

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      if (activeCursors) activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      if (visualLatchedNodes) visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (!latched || latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || !visualLatchedNodes || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n && modeMap) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && data.nodes.length > 0) {
          const t = setTimeout(() => {
              centerScroll();
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);

  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;

      // Calculate Scroll Position manually since canvases are fixed
      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const rect = scrollContainerRef.current.getBoundingClientRect();
      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      // Apply Pitch Bend offset to hit detection
      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap && latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      // Track raw client position for render feedback
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     // Reverse Logic: Don't unlatch, trigger group bend
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; 
                     } else {
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 if (isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; 
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    // Convert client coords to relative viewport coords for renderer (it handles translation)
    // For fixed canvases, we pass the CLIENT coords relative to the container directly
    // IF the renderer uses translate(-viewX), we must supply world coords?
    // Let's check LatticeRenderer.renderStatic: it translates by -view.x. 
    // So we need to give it cursor position in WORLD space for drawing the line? 
    // No, renderDynamic iterates activeCursors.
    // If activeCursors store WORLD pos? Or Client pos?
    // Let's store client pos in cursorPositionsRef, but renderer uses it directly.
    // Wait, renderer draws line from Node (World) to Cursor.
    // Node is World - Scroll. Cursor is Client.
    // Renderer translates by -Scroll.
    // So Node is drawn at (World - Scroll).
    // Cursor is at Client.
    // If renderer draws line to Cursor, it must inverse translate the cursor?
    // Or simpler: We store cursor position as (Client + Scroll) = World space.

    let worldX = e.clientX;
    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
        worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
    }
    cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;

             // Calculate bend using WORLD Y
             const originWorldY = (originNode.y * spacing) + centerOffset;

             // We need current World Y, adjusted for any global pitch offset
             const bend = globalBendRef.current;
             const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

             const currentDeltaY = (worldY - pixelOffset) - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             if (cursor.isGroupBend) {
                 // Group Bend: Iterate all latched nodes
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap && modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 // Standard Single Voice Bend
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap && modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              return { ...baseStyle, background: `linear-gradient(to bottom, #111, #222)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div className="relative w-full h-full bg-slate-950 overflow-hidden">
        {/* Canvases Fixed to Viewport (Stationary) */}
        <canvas ref={bgLineCanvasRef} className="absolute inset-0 z-[5] pointer-events-none" />
        <canvas ref={staticCanvasRef} className="absolute inset-0 z-[10] pointer-events-none" />
        <canvas ref={dynamicCanvasRef} className="absolute inset-0 z-[20] pointer-events-none" />

        {/* Scroll Container (Transparent Overlay handling scroll state and interaction) */}
        <div 
            ref={scrollContainerRef} 
            className="absolute inset-0 overflow-auto z-[30]" 
            style={{ touchAction: 'none' }}
            onPointerDown={handlePointerDown} 
            onPointerMove={handlePointerMove} 
            onPointerUp={handlePointerUp} 
            onPointerLeave={handlePointerUp} 
            onPointerCancel={handlePointerUp}
        >
            <div className="relative" style={getBackgroundStyle()}>
               {/* Content div sets the scrollable area size */}
               {isGenerating && (<div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
            </div>
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, SynthPreset, PresetSlot, PlaybackMode, LimitType } from '../types';
import { PITCH_SCALE, getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import { GRID_CELL_SIZE } from '../constants';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  isCurrentSustainEnabled: boolean;
  globalScale?: number;
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              if (modeMap) modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      if (persistentLatches) {
          persistentLatches.forEach((modeMap, nodeId) => {
              const activations: NodeActivation[] = [];
              if (modeMap) {
                  modeMap.forEach((timestamp, mode) => {
                      let pId = 'normal';
                      if (mode === 1) pId = 'latch';
                      else if (mode === 3) pId = 'strum';
                      else if (mode === 4) pId = 'brass';
                      else if (mode === 5) pId = 'keys';
                      else if (mode === 6) pId = 'percussion';
                      activations.push({ mode, timestamp, presetId: pId });
                  });
              }
              effective.set(nodeId, activations);
          });
      }

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      if (audioLatchedNodes) audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      if (activeCursors) {
          activeCursors.forEach(cursor => {
              const isSustainingInstrument = latchMode >= 1; 
              const isSustainActive = isCurrentSustainEnabled;
              const isBendEnabled = settings.isPitchBendEnabled;

              const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
              if (isHybridMode) return; 

              const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
              if (isMelodic && cursor.hoverNodeId) {
                  const nodeId = cursor.hoverNodeId;
                  if (!visual.has(nodeId)) visual.set(nodeId, []);
                  const list = visual.get(nodeId)!;
                  const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
                  list.push(activation);
                  list.sort((a, b) => a.timestamp - b.timestamp);
              }
          });
      }

      if (externalTriggers) {
          externalTriggers.forEach((timestamp, nodeId) => {
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          });
      }

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      if (activeCursors) activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      if (visualLatchedNodes) visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (!latched || latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || !visualLatchedNodes || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n && modeMap) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && data.nodes.length > 0) {
          const t = setTimeout(() => {
              centerScroll();
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);

  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const rect = scrollContainerRef.current.getBoundingClientRect();
      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap && latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      let worldX = e.clientX;
      let worldY = e.clientY;
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
          worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
      }
      cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; 
                     } else {
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 if (isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; 
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldX = e.clientX;
    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
        worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
    }
    cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;

             const bend = globalBendRef.current;
             const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

             const currentDeltaY = (worldY - pixelOffset) - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             if (cursor.isGroupBend) {
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap && modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap && modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              return { ...baseStyle, background: `linear-gradient(to bottom, #111, #222)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div className="relative w-full h-full bg-slate-950 overflow-hidden">
        {/* Scroll Container (Layer 1 - Bottom) */}
        {/* Handles Background & Interaction */}
        <div 
            ref={scrollContainerRef} 
            className="absolute inset-0 overflow-auto z-[10]" 
            style={{ touchAction: 'none' }}
            onPointerDown={handlePointerDown} 
            onPointerMove={handlePointerMove} 
            onPointerUp={handlePointerUp} 
            onPointerLeave={handlePointerUp} 
            onPointerCancel={handlePointerUp}
        >
            <div className="relative" style={getBackgroundStyle()}>
               {/* Content div sets the scrollable area size */}
               {isGenerating && (<div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
            </div>
        </div>

        {/* Canvases (Layer 2 - Top) */}
        {/* Fixed position, transparent, pass-through events */}
        <canvas ref={bgLineCanvasRef} className="absolute inset-0 z-[20] pointer-events-none" />
        <canvas ref={staticCanvasRef} className="absolute inset-0 z-[30] pointer-events-none" />
        <canvas ref={dynamicCanvasRef} className="absolute inset-0 z-[40] pointer-events-none" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    const t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

// Optimization: Use plain objects instead of Class to reduce GC pressure
interface Fraction {
    n: number;
    d: number;
}

const createFraction = (n: number, d: number): Fraction => {
    const common = gcd(n, d);
    return { n: n / common, d: d / common };
};

const mulFractions = (a: Fraction, b: Fraction): Fraction => {
    return createFraction(a.n * b.n, a.d * b.d);
};

const normalizeFraction = (f: Fraction): Fraction => {
    let nn = f.n;
    let dd = f.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return createFraction(nn, dd);
};

const shiftOctave = (f: Fraction, octave: number): Fraction => {
    let nn = f.n;
    let dd = f.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return createFraction(nn, dd);
};

const PRIMES = [3, 5, 7, 9, 11, 13, 15];
const PRIME_RATIOS: Record<number, Fraction> = {
  3: createFraction(3, 2),
  5: createFraction(5, 4),
  7: createFraction(7, 4),
  9: createFraction(9, 8),
  11: createFraction(11, 8),
  13: createFraction(13, 8),
  15: createFraction(15, 8),
};

const ODD_IDENTITIES = [1, 3, 5, 7, 9, 11, 13, 15];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = createFraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx] || 0;
          const pRat = PRIME_RATIOS[p];
          for(let i=0; i<Math.abs(val); i++) {
              if (val > 0) {
                  originFrac = normalizeFraction(mulFractions(originFrac, pRat));
              } else {
                  originFrac = normalizeFraction(mulFractions(originFrac, { n: pRat.d, d: pRat.n }));
              }
          }
      });

      localQueue.push({ coords: origin.coords, ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 1200;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = shiftOctave(current.ratio, oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          for (let idx = 0; idx < PRIMES.length; idx++) {
              const prime = PRIMES[idx];
              // @ts-ignore
              const depthLimit = settings.limitDepths[prime];
              if (depthLimit <= 0) continue;

              const originVal = origin.coords[idx] || 0;
              const currentVal = current.coords[idx] || 0;

              const dirs = [1, -1];
              for (let dIdx = 0; dIdx < dirs.length; dIdx++) {
                  const dir = dirs[dIdx];
                  if (Math.abs((currentVal + dir) - originVal) > depthLimit) continue;

                  const nextCoords = current.coords.slice();
                  // Ensure coords array is long enough 
                  while(nextCoords.length <= idx) nextCoords.push(0);

                  nextCoords[idx] += dir;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime];
                      let nextFrac: Fraction;
                      if (dir === 1) {
                          nextFrac = normalizeFraction(mulFractions(current.ratio, pRat));
                      } else {
                          nextFrac = normalizeFraction(mulFractions(current.ratio, { n: pRat.d, d: pRat.n }));
                      }

                      let isComplexValid = true;
                      for (let i = 0; i < PRIMES.length; i++) {
                          const p = PRIMES[i];
                          const coordVal = nextCoords[i] || 0;

                          if (coordVal !== 0) {
                              // @ts-ignore
                              const limit = settings.limitComplexities[p];
                              if (limit !== undefined) {
                                  if (nextFrac.n > limit || nextFrac.d > limit) {
                                      isComplexValid = false;
                                      break;
                                  }
                              }
                          }
                      }

                      if (isComplexValid) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              }
          }
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  for (const node of nodes) {
      for (let idx = 0; idx < PRIMES.length; idx++) {
          const prime = PRIMES[idx];

          const targetCoords = node.coords.slice();
          while(targetCoords.length <= idx) targetCoords.push(0);
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              const target = nodesMap.get(targetId);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const primeRat = PRIME_RATIOS[prime];
                  const test = ratio / (primeRat.n / primeRat.d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      }
  }

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    const activeIdentities = ODD_IDENTITIES.filter(id => !settings.hiddenLimits.includes(id));
    const N = activeIdentities.length;

    // Scale factor to ensure nodes are visually separated
    const diamondSpacing = 200; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = normalizeFraction(createFraction(idOton, idUton));
            const ratio = frac.n / frac.d;

            // Layout indices rotated 45 degrees
            // Removing the 0.8 Y-factor to ensure square aspect ratio for better touch targets
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            const id = `diamond-${o}-${u}`;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y, 
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, SynthPreset, PresetSlot, PlaybackMode, LimitType } from '../types';
import { PITCH_SCALE, getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import { GRID_CELL_SIZE } from '../constants';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  isCurrentSustainEnabled: boolean;
  globalScale?: number;
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              if (modeMap) modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      if (persistentLatches) {
          persistentLatches.forEach((modeMap, nodeId) => {
              const activations: NodeActivation[] = [];
              if (modeMap) {
                  modeMap.forEach((timestamp, mode) => {
                      let pId = 'normal';
                      if (mode === 1) pId = 'latch';
                      else if (mode === 3) pId = 'strum';
                      else if (mode === 4) pId = 'brass';
                      else if (mode === 5) pId = 'keys';
                      else if (mode === 6) pId = 'percussion';
                      activations.push({ mode, timestamp, presetId: pId });
                  });
              }
              effective.set(nodeId, activations);
          });
      }

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      if (audioLatchedNodes) audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      if (activeCursors) {
          activeCursors.forEach(cursor => {
              const isSustainingInstrument = latchMode >= 1; 
              const isSustainActive = isCurrentSustainEnabled;
              const isBendEnabled = settings.isPitchBendEnabled;

              const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
              if (isHybridMode) return; 

              const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
              if (isMelodic && cursor.hoverNodeId) {
                  const nodeId = cursor.hoverNodeId;
                  if (!visual.has(nodeId)) visual.set(nodeId, []);
                  const list = visual.get(nodeId)!;
                  const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
                  list.push(activation);
                  list.sort((a, b) => a.timestamp - b.timestamp);
              }
          });
      }

      if (externalTriggers) {
          externalTriggers.forEach((timestamp, nodeId) => {
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          });
      }

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      if (activeCursors) activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      if (visualLatchedNodes) visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (!latched || latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || !visualLatchedNodes || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  // ALWAYS update refs on every render to avoid stale closure state in event handlers
  useEffect(() => { settingsRef.current = settings; });
  useEffect(() => { dataRef.current = data; });
  useEffect(() => { activeCursorsRef.current = activeCursors; });
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; });
  useEffect(() => { activeLinesRef.current = activeLines; });
  useEffect(() => { brightenedLinesRef.current = brightenedLines; });
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; });
  useEffect(() => { effectiveScaleRef.current = effectiveScale; });
  useEffect(() => { latchModeRef.current = latchMode; });
  useEffect(() => { nodeMapRef.current = nodeMap; });
  useEffect(() => { spatialGridRef.current = spatialGrid; });
  useEffect(() => { persistentLatchesRef.current = persistentLatches; });
  useEffect(() => { centerOffsetRef.current = centerOffset; });
  useEffect(() => { dynamicSizeRef.current = dynamicSize; });

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n && modeMap) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && data.nodes.length > 0) {
          const t = setTimeout(() => {
              centerScroll();
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);

  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- HIT TEST LOGIC ---
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const bend = globalBendRef.current;

      // Use Ref for scale to avoid stale state in callbacks
      const currentEffectiveScale = effectiveScaleRef.current;

      const pixelOffset = -bend * (PITCH_SCALE / 12) * currentEffectiveScale;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const currentSpacing = settingsRef.current.buttonSpacingScale * currentEffectiveScale;
      // Use Ref for dynamicSize to ensure we use the latest computed center
      const currentCenterOffset = dynamicSizeRef.current / 2;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * currentEffectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * currentSpacing + currentCenterOffset;
                  const ny = node.y * currentSpacing + currentCenterOffset;

                  const isLatched = latchedMap && latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  const dx = x - nx;
                  const dy = y - ny;

                  // Use a slightly larger hit target for small screens/fingers
                  const hitRadius = Math.max(activeRadius, 20); 

                  if (dx*dx + dy*dy < hitRadius*hitRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      let worldX = e.clientX;
      let worldY = e.clientY;
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
          worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
      }
      cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; 
                     } else {
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 if (isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; 
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldX = e.clientX;
    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
        worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
    }
    cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScaleRef.current;
             const originWorldY = (originNode.y * spacing) + centerOffsetRef.current;

             const bend = globalBendRef.current;
             const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScaleRef.current;

             const currentDeltaY = (worldY - pixelOffset) - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScaleRef.current);

             if (cursor.isGroupBend) {
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap && modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap && modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              return { ...baseStyle, background: `linear-gradient(to bottom, #111, #222)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div className="relative w-full h-full bg-slate-950 overflow-hidden">
        {/* Scroll Container (Layer 1 - Bottom) */}
        {/* Handles Background & Interaction */}
        <div 
            ref={scrollContainerRef} 
            className="absolute inset-0 overflow-auto z-[10]" 
            style={{ touchAction: 'none' }}
            onPointerDown={handlePointerDown} 
            onPointerMove={handlePointerMove} 
            onPointerUp={handlePointerUp} 
            onPointerLeave={handlePointerUp} 
            onPointerCancel={handlePointerUp}
        >
            <div className="relative pointer-events-none" style={getBackgroundStyle()}>
               {/* Content div sets the scrollable area size */}
               {isGenerating && (<div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
            </div>
        </div>

        {/* Canvases (Layer 2 - Top) */}
        {/* Fixed position, transparent, pass-through events */}
        <canvas ref={bgLineCanvasRef} className="absolute inset-0 z-[20] pointer-events-none" />
        <canvas ref={staticCanvasRef} className="absolute inset-0 z-[30] pointer-events-none" />
        <canvas ref={dynamicCanvasRef} className="absolute inset-0 z-[40] pointer-events-none" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    const t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

// Optimization: Use plain objects instead of Class to reduce GC pressure
interface Fraction {
    n: number;
    d: number;
}

const createFraction = (n: number, d: number): Fraction => {
    const common = gcd(n, d);
    return { n: n / common, d: d / common };
};

const mulFractions = (a: Fraction, b: Fraction): Fraction => {
    return createFraction(a.n * b.n, a.d * b.d);
};

const normalizeFraction = (f: Fraction): Fraction => {
    let nn = f.n;
    let dd = f.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return createFraction(nn, dd);
};

const shiftOctave = (f: Fraction, octave: number): Fraction => {
    let nn = f.n;
    let dd = f.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return createFraction(nn, dd);
};

const PRIMES = [3, 5, 7, 9, 11, 13, 15];
const PRIME_RATIOS: Record<number, Fraction> = {
  3: createFraction(3, 2),
  5: createFraction(5, 4),
  7: createFraction(7, 4),
  9: createFraction(9, 8),
  11: createFraction(11, 8),
  13: createFraction(13, 8),
  15: createFraction(15, 8),
};

const ODD_IDENTITIES = [1, 3, 5, 7, 9, 11, 13, 15];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = createFraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx] || 0;
          const pRat = PRIME_RATIOS[p];
          for(let i=0; i<Math.abs(val); i++) {
              if (val > 0) {
                  originFrac = normalizeFraction(mulFractions(originFrac, pRat));
              } else {
                  originFrac = normalizeFraction(mulFractions(originFrac, { n: pRat.d, d: pRat.n }));
              }
          }
      });

      localQueue.push({ coords: origin.coords, ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 1200;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = shiftOctave(current.ratio, oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          for (let idx = 0; idx < PRIMES.length; idx++) {
              const prime = PRIMES[idx];
              // @ts-ignore
              const depthLimit = settings.limitDepths ? settings.limitDepths[prime] : 0;
              if (depthLimit <= 0) continue;

              const originVal = origin.coords[idx] || 0;
              const currentVal = current.coords[idx] || 0;

              const dirs = [1, -1];
              for (let dIdx = 0; dIdx < dirs.length; dIdx++) {
                  const dir = dirs[dIdx];
                  if (Math.abs((currentVal + dir) - originVal) > depthLimit) continue;

                  const nextCoords = current.coords.slice();
                  // Ensure coords array is long enough 
                  while(nextCoords.length <= idx) nextCoords.push(0);

                  nextCoords[idx] += dir;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime];
                      let nextFrac: Fraction;
                      if (dir === 1) {
                          nextFrac = normalizeFraction(mulFractions(current.ratio, pRat));
                      } else {
                          nextFrac = normalizeFraction(mulFractions(current.ratio, { n: pRat.d, d: pRat.n }));
                      }

                      let isComplexValid = true;
                      // Safe Complexity Check
                      // @ts-ignore
                      if (settings.limitComplexities) {
                          for (let i = 0; i < PRIMES.length; i++) {
                              const p = PRIMES[i];
                              const coordVal = nextCoords[i] || 0;

                              if (coordVal !== 0) {
                                  // @ts-ignore
                                  const limit = settings.limitComplexities[p];
                                  if (limit !== undefined) {
                                      if (nextFrac.n > limit || nextFrac.d > limit) {
                                          isComplexValid = false;
                                          break;
                                      }
                                  }
                              }
                          }
                      }

                      if (isComplexValid) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              }
          }
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  for (const node of nodes) {
      for (let idx = 0; idx < PRIMES.length; idx++) {
          const prime = PRIMES[idx];

          const targetCoords = node.coords.slice();
          while(targetCoords.length <= idx) targetCoords.push(0);
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              const target = nodesMap.get(targetId);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const primeRat = PRIME_RATIOS[prime];
                  const test = ratio / (primeRat.n / primeRat.d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      }
  }

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    const activeIdentities = ODD_IDENTITIES.filter(id => !settings.hiddenLimits.includes(id));
    const N = activeIdentities.length;

    // Scale factor to ensure nodes are visually separated
    const diamondSpacing = 200; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = normalizeFraction(createFraction(idOton, idUton));
            const ratio = frac.n / frac.d;

            // Layout indices rotated 45 degrees
            // Removing the 0.8 Y-factor to ensure square aspect ratio for better touch targets
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            const id = `diamond-${o}-${u}`;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y, 
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

const ODD_IDENTITIES = [1, 3, 5, 7, 11, 13];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p as 3|5|7|11|13];
          for(let i=0; i<Math.abs(val); i++) {
              originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
          }
      });

      localQueue.push({ coords: origin.coords, ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 800;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime as 3|5|7|11|13];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      // @ts-ignore
                      const compLimit = (settings.limitComplexities && settings.limitComplexities[prime as 3|5|7|11|13]) ? settings.limitComplexities[prime as 3|5|7|11|13] : 1000;
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / (PRIME_RATIOS[prime as 3|5|7|11|13].n / PRIME_RATIOS[prime as 3|5|7|11|13].d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Find highest enabled odd limit
    let maxEnabledLimit = 1;
    settings.layerOrder.forEach(l => {
        if (!settings.hiddenLimits.includes(l) && ODD_IDENTITIES.includes(l)) {
            if (l > maxEnabledLimit) maxEnabledLimit = l;
        }
    });

    const activeIdentities = ODD_IDENTITIES.filter(id => id <= maxEnabledLimit);
    const N = activeIdentities.length;

    // Use standard spacing without vertical squash
    const diamondSpacing = 150; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Layout indices rotated 45 degrees
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            const id = `diamond-${o}-${u}`;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], // Not standard prime coords, but used for grid
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y, 
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, SynthPreset, PresetSlot, PlaybackMode, LimitType } from '../types';
import { PITCH_SCALE, getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import { GRID_CELL_SIZE } from '../constants';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  isCurrentSustainEnabled: boolean;
  globalScale?: number;
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              if (modeMap) modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      if (persistentLatches) {
          persistentLatches.forEach((modeMap, nodeId) => {
              const activations: NodeActivation[] = [];
              if (modeMap) {
                  modeMap.forEach((timestamp, mode) => {
                      let pId = 'normal';
                      if (mode === 1) pId = 'latch';
                      else if (mode === 3) pId = 'strum';
                      else if (mode === 4) pId = 'brass';
                      else if (mode === 5) pId = 'keys';
                      else if (mode === 6) pId = 'percussion';
                      activations.push({ mode, timestamp, presetId: pId });
                  });
              }
              effective.set(nodeId, activations);
          });
      }

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      if (audioLatchedNodes) audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      if (activeCursors) {
          activeCursors.forEach(cursor => {
              const isSustainingInstrument = latchMode >= 1; 
              const isSustainActive = isCurrentSustainEnabled;
              const isBendEnabled = settings.isPitchBendEnabled;

              const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
              if (isHybridMode) return; 

              const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
              if (isMelodic && cursor.hoverNodeId) {
                  const nodeId = cursor.hoverNodeId;
                  if (!visual.has(nodeId)) visual.set(nodeId, []);
                  const list = visual.get(nodeId)!;
                  const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
                  list.push(activation);
                  list.sort((a, b) => a.timestamp - b.timestamp);
              }
          });
      }

      if (externalTriggers) {
          externalTriggers.forEach((timestamp, nodeId) => {
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          });
      }

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      if (activeCursors) activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      if (visualLatchedNodes) visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (!latched || latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || !visualLatchedNodes || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  // ALWAYS update refs on every render to avoid stale closure state in event handlers
  useEffect(() => { settingsRef.current = settings; });
  useEffect(() => { dataRef.current = data; });
  useEffect(() => { activeCursorsRef.current = activeCursors; });
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; });
  useEffect(() => { activeLinesRef.current = activeLines; });
  useEffect(() => { brightenedLinesRef.current = brightenedLines; });
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; });
  useEffect(() => { effectiveScaleRef.current = effectiveScale; });
  useEffect(() => { latchModeRef.current = latchMode; });
  useEffect(() => { nodeMapRef.current = nodeMap; });
  useEffect(() => { spatialGridRef.current = spatialGrid; });
  useEffect(() => { persistentLatchesRef.current = persistentLatches; });
  useEffect(() => { centerOffsetRef.current = centerOffset; });
  useEffect(() => { dynamicSizeRef.current = dynamicSize; });

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n && modeMap) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && data.nodes.length > 0) {
          const t = setTimeout(() => {
              centerScroll();
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);

  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- HIT TEST LOGIC ---
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const bend = globalBendRef.current;

      const currentEffectiveScale = effectiveScaleRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * currentEffectiveScale;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const currentSpacing = settingsRef.current.buttonSpacingScale * currentEffectiveScale;
      // CRITICAL: Must use centerOffsetRef which comes from useLatticeData hook, NOT dynamicSize / 2
      // The hook handles the dynamic resizing logic which might be slightly ahead/behind render cycle
      const currentCenterOffset = centerOffsetRef.current;

      const baseRadius = (60 * settingsRef.current.buttonSizeScale * currentEffectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * currentSpacing + currentCenterOffset;
                  const ny = node.y * currentSpacing + currentCenterOffset;

                  // Match visual radius logic from LatticeRenderer
                  // It uses limitVisuals to scale the visual node
                  const vis = settingsRef.current.limitVisuals?.[node.limitTop] || { size: 1 };
                  const limitScale = vis.size ?? 1;

                  const isLatched = latchedMap && latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;

                  // Combine all scaling factors
                  const activeRadius = baseRadius * limitScale * activeZoom;

                  const dx = x - nx;
                  const dy = y - ny;

                  // Ensure hitbox is at least touchable size (20px radius = 40px diameter)
                  // But respect large visual nodes
                  const hitRadius = Math.max(activeRadius, 20); 

                  if (dx*dx + dy*dy < hitRadius*hitRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      let worldX = e.clientX;
      let worldY = e.clientY;
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
          worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
      }
      cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; 
                     } else {
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 if (isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; 
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldX = e.clientX;
    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
        worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
    }
    cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScaleRef.current;
             const originWorldY = (originNode.y * spacing) + centerOffsetRef.current;

             const bend = globalBendRef.current;
             const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScaleRef.current;

             const currentDeltaY = (worldY - pixelOffset) - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScaleRef.current);

             if (cursor.isGroupBend) {
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap && modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap && modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              return { ...baseStyle, background: `linear-gradient(to bottom, #111, #222)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div className="relative w-full h-full bg-slate-950 overflow-hidden">
        {/* Scroll Container (Layer 1 - Bottom) */}
        {/* Handles Background & Interaction */}
        <div 
            ref={scrollContainerRef} 
            className="absolute inset-0 overflow-auto z-[10]" 
            style={{ touchAction: 'none' }}
            onPointerDown={handlePointerDown} 
            onPointerMove={handlePointerMove} 
            onPointerUp={handlePointerUp} 
            onPointerLeave={handlePointerUp} 
            onPointerCancel={handlePointerUp}
        >
            <div className="relative pointer-events-none" style={getBackgroundStyle()}>
               {/* Content div sets the scrollable area size */}
               {isGenerating && (<div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
            </div>
        </div>

        {/* Canvases (Layer 2 - Top) */}
        {/* Fixed position, transparent, pass-through events */}
        <canvas ref={bgLineCanvasRef} className="absolute inset-0 z-[20] pointer-events-none" />
        <canvas ref={staticCanvasRef} className="absolute inset-0 z-[30] pointer-events-none" />
        <canvas ref={dynamicCanvasRef} className="absolute inset-0 z-[40] pointer-events-none" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

const ODD_IDENTITIES = [1, 3, 5, 7, 11, 13];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p as 3|5|7|11|13];
          for(let i=0; i<Math.abs(val); i++) {
              originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
          }
      });

      localQueue.push({ coords: origin.coords, ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 800;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime as 3|5|7|11|13];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      // @ts-ignore
                      const compLimit = (settings.limitComplexities && settings.limitComplexities[prime as 3|5|7|11|13]) ? settings.limitComplexities[prime as 3|5|7|11|13] : 1000;
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / (PRIME_RATIOS[prime as 3|5|7|11|13].n / PRIME_RATIOS[prime as 3|5|7|11|13].d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Find highest enabled odd limit
    let maxEnabledLimit = 1;
    settings.layerOrder.forEach(l => {
        if (!settings.hiddenLimits.includes(l) && ODD_IDENTITIES.includes(l)) {
            if (l > maxEnabledLimit) maxEnabledLimit = l;
        }
    });

    const activeIdentities = ODD_IDENTITIES.filter(id => id <= maxEnabledLimit);
    const N = activeIdentities.length;

    // Use standard spacing without vertical squash
    const diamondSpacing = 150; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Layout indices rotated 45 degrees
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            const id = `diamond-${o}-${u}`;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], // Not standard prime coords, but used for grid
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y, 
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, SynthPreset, PresetSlot, PlaybackMode, LimitType } from '../types';
import { PITCH_SCALE, getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import { GRID_CELL_SIZE } from '../constants';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  isCurrentSustainEnabled: boolean;
  globalScale?: number;
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
  isGroupBend?: boolean;
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              if (modeMap) modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      if (persistentLatches) {
          persistentLatches.forEach((modeMap, nodeId) => {
              const activations: NodeActivation[] = [];
              if (modeMap) {
                  modeMap.forEach((timestamp, mode) => {
                      let pId = 'normal';
                      if (mode === 1) pId = 'latch';
                      else if (mode === 3) pId = 'strum';
                      else if (mode === 4) pId = 'brass';
                      else if (mode === 5) pId = 'keys';
                      else if (mode === 6) pId = 'percussion';
                      activations.push({ mode, timestamp, presetId: pId });
                  });
              }
              effective.set(nodeId, activations);
          });
      }

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      if (audioLatchedNodes) audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      if (activeCursors) {
          activeCursors.forEach(cursor => {
              const isSustainingInstrument = latchMode >= 1; 
              const isSustainActive = isCurrentSustainEnabled;
              const isBendEnabled = settings.isPitchBendEnabled;

              const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
              if (isHybridMode) return; 

              const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
              if (isMelodic && cursor.hoverNodeId) {
                  const nodeId = cursor.hoverNodeId;
                  if (!visual.has(nodeId)) visual.set(nodeId, []);
                  const list = visual.get(nodeId)!;
                  const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
                  list.push(activation);
                  list.sort((a, b) => a.timestamp - b.timestamp);
              }
          });
      }

      if (externalTriggers) {
          externalTriggers.forEach((timestamp, nodeId) => {
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          });
      }

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      if (activeCursors) activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      if (visualLatchedNodes) visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (!latched || latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || !visualLatchedNodes || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);
  const prevCenterOffsetRef = useRef(centerOffset);
  const dynamicSizeRef = useRef(dynamicSize);

  // ALWAYS update refs on every render to avoid stale closure state in event handlers
  useEffect(() => { settingsRef.current = settings; });
  useEffect(() => { dataRef.current = data; });
  useEffect(() => { activeCursorsRef.current = activeCursors; });
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; });
  useEffect(() => { activeLinesRef.current = activeLines; });
  useEffect(() => { brightenedLinesRef.current = brightenedLines; });
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; });
  useEffect(() => { effectiveScaleRef.current = effectiveScale; });
  useEffect(() => { latchModeRef.current = latchMode; });
  useEffect(() => { nodeMapRef.current = nodeMap; });
  useEffect(() => { spatialGridRef.current = spatialGrid; });
  useEffect(() => { persistentLatchesRef.current = persistentLatches; });
  useEffect(() => { centerOffsetRef.current = centerOffset; });
  useEffect(() => { dynamicSizeRef.current = dynamicSize; });

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n && modeMap) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && data.nodes.length > 0) {
          const t = setTimeout(() => {
              centerScroll();
              if (dynamicSize > 0) setIsInitialLoad(false);
          }, 100);
          return () => clearTimeout(t);
      }
  }, [data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Dynamic Resize Scroll Compensation
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldOffset = prevCenterOffsetRef.current;
      const newOffset = centerOffset;

      if (oldOffset !== newOffset && !isInitialLoad) {
          const delta = newOffset - oldOffset;
          container.scrollLeft += delta;
          container.scrollTop += delta;
      }
      prevCenterOffsetRef.current = newOffset;
  }, [centerOffset, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);

  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- HIT TEST LOGIC ---
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const bend = globalBendRef.current;

      const currentEffectiveScale = effectiveScaleRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * currentEffectiveScale;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const currentSpacing = settingsRef.current.buttonSpacingScale * currentEffectiveScale;
      // CRITICAL: Must use centerOffsetRef which comes from useLatticeData hook, NOT dynamicSize / 2
      // The hook handles the dynamic resizing logic which might be slightly ahead/behind render cycle
      const currentCenterOffset = centerOffsetRef.current;

      const baseRadius = (60 * settingsRef.current.buttonSizeScale * currentEffectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              // Iterate in reverse to prioritize nodes drawn "on top"
              for (let i = nodesInCell.length - 1; i >= 0; i--) {
                  const node = nodesInCell[i];
                  const nx = node.x * currentSpacing + currentCenterOffset;
                  const ny = node.y * currentSpacing + currentCenterOffset;

                  // Match visual radius logic from LatticeRenderer
                  // It uses limitVisuals to scale the visual node
                  const vis = settingsRef.current.limitVisuals?.[node.limitTop] || { size: 1 };
                  const limitScale = vis.size ?? 1;

                  const isLatched = latchedMap && latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;

                  // Combine all scaling factors
                  const activeRadius = baseRadius * limitScale * activeZoom;

                  const dx = x - nx;
                  const dy = y - ny;

                  // Ensure hitbox is at least touchable size (20px radius = 40px diameter)
                  // But respect large visual nodes
                  const hitRadius = Math.max(activeRadius, 20); 

                  if (dx*dx + dy*dy < hitRadius*hitRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      let worldX = e.clientX;
      let worldY = e.clientY;
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
          worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
      }
      cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      let isGroupBend = false;
      let shouldStartCursorVoice = true;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument) {
             const currentModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = currentModes && currentModes.has(latchMode);

             if (isSustainActive) {
                 if (isAlreadyLatched) {
                     if (isBendEnabled) {
                         isGroupBend = true;
                         shouldStartCursorVoice = false; 
                     } else {
                         shouldStartCursorVoice = false;
                     }
                 } else {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                 }
             } else {
                 if (isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id);
                         if (nodeModes) {
                             nodeModes.delete(latchMode);
                             if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                             else next.delete(hitNode.id);
                         }
                         return next;
                     });
                     shouldStartCursorVoice = false; 
                 }
             }
        }

        if (shouldStartCursorVoice && (isBendEnabled || !isSustainActive)) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: isGroupBend
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            if (!isGroupBend) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
                audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        } else if (isGroupBend) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isGroupBend: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldX = e.clientX;
    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        worldX = (e.clientX - r.left) + scrollContainerRef.current.scrollLeft;
        worldY = (e.clientY - r.top) + scrollContainerRef.current.scrollTop;
    }
    cursorPositionsRef.current.set(e.pointerId, { x: worldX, y: worldY });

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScaleRef.current;
             const originWorldY = (originNode.y * spacing) + centerOffsetRef.current;

             const bend = globalBendRef.current;
             const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScaleRef.current;

             const currentDeltaY = (worldY - pixelOffset) - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScaleRef.current);

             if (cursor.isGroupBend) {
                 const activeNodes = persistentLatchesRef.current;
                 activeNodes.forEach((modeMap, nodeId) => {
                     if (modeMap && modeMap.has(latchMode)) {
                         const n = nodeMapRef.current.get(nodeId);
                         if (n) {
                             const finalRatio = n.ratio * bentRatio;
                             const voiceId = `node-${nodeId}-${latchMode}`;
                             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                             if (settingsRef.current.midiEnabled) {
                                 midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                             }
                         }
                     }
                 });
             } else {
                 const finalRatio = originNode.ratio * bentRatio;
                 const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                 audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
                 if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !cursor.isGroupBend) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!cursor.isGroupBend) {
            if (!shouldSustainBend && cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(oldVoiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
                 }
            }

            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

                 if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                    const isDifferentNode = hitNode.id !== cursor.originNodeId;
                    if (hasMoved || isDifferentNode) {
                        const currentModes = persistentLatchesRef.current.get(hitNode.id);
                        const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                        if (!isAlreadyLatched) { 
                            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                                const next = new Map(prev);
                                const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                                nodeModes.set(latchMode, Date.now());
                                next.set(hitNode.id, nodeModes);
                                return next;
                            });
                            nodeTriggerHistory.current.set(hitNode.id, Date.now());
                        }
                    }
                 } 
                 else if (!isBending) {
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());

                     const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                     const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                     audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                     if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                 }
            }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.isGroupBend) {
             const activeNodes = persistentLatchesRef.current;
             activeNodes.forEach((modeMap, nodeId) => {
                 if (modeMap && modeMap.has(latchMode)) {
                     const n = nodeMapRef.current.get(nodeId);
                     if (n) {
                         const voiceId = `node-${nodeId}-${latchMode}`;
                         audioEngine.glideVoice(voiceId, n.ratio, settingsRef.current.baseFrequency);
                         if (settingsRef.current.midiEnabled) {
                             midiService.pitchBend(voiceId, n.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
                         }
                     }
                 }
             });
        }
        else if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              return { ...baseStyle, background: `linear-gradient(to bottom, #111, #222)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div className="relative w-full h-full bg-slate-950 overflow-hidden">
        {/* Scroll Container (Layer 1 - Bottom) */}
        {/* Handles Background & Interaction */}
        <div 
            ref={scrollContainerRef} 
            className="absolute inset-0 overflow-auto z-[10]" 
            style={{ touchAction: 'none' }}
            onPointerDown={handlePointerDown} 
            onPointerMove={handlePointerMove} 
            onPointerUp={handlePointerUp} 
            onPointerLeave={handlePointerUp} 
            onPointerCancel={handlePointerUp}
        >
            <div className="relative pointer-events-none" style={getBackgroundStyle()}>
               {/* Content div sets the scrollable area size */}
               {isGenerating && (<div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
            </div>
        </div>

        {/* Canvases (Layer 2 - Top) */}
        {/* Fixed position, transparent, pass-through events */}
        {/* MOVED OUTSIDE of scrollContainerRef to prevent double-scroll translation and fix squish issues */}
        <canvas ref={bgLineCanvasRef} className="absolute inset-0 z-[20] pointer-events-none" />
        <canvas ref={staticCanvasRef} className="absolute inset-0 z-[30] pointer-events-none" />
        <canvas ref={dynamicCanvasRef} className="absolute inset-0 z-[40] pointer-events-none" />
    </div>
  );
});

export default React.memo(TonalityDiamond);
